use vstd::prelude::*;

verus! {

spec fn is_4_digit(n: int) -> bool {
    1000 <= n && n <= 9999
}

spec fn digit(n: int, place: nat) -> nat
    decreases place
{
    // place: 0 = ones, 1 = tens, 2 = hundreds, 3 = thousands
    if place == 0 {
        (n % 10) as nat
    } else {
        ((n / (int::pow(10, place as u32))) % 10) as nat
    }
}

fn solve(n: i8) -> (res: bool)
    ensures
        res == (
            is_4_digit(n as int) &&
            (
                (digit(n as int, 3) == digit(n as int, 2) && digit(n as int, 2) == digit(n as int, 1)) ||
                (digit(n as int, 2) == digit(n as int, 1) && digit(n as int, 1) == digit(n as int, 0))
            )
        )
{
    let num = n as i32;

    if num < 1000 || num > 9999 {
        return false;
    }

    let thousands = (num / 1000) % 10;
    let hundreds = (num / 100) % 10;
    let tens = (num / 10) % 10;
    let ones = num % 10;

    let first_three_equal = (thousands == hundreds) && (hundreds == tens);
    let last_three_equal = (hundreds == tens) && (tens == ones);

    first_three_equal || last_three_equal
}

}